// Spare Parts Printer - fabrication planner (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var spd=[0.5,40,3000], res=[200,5,0.05];
var jobs=[["hand tool",2],["vehicle engine",400],["habitat module",20000]];
console.log("Spare Parts Printer - build time estimates");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": "+spd[m]+" kg/h at "+res[m]+" micron resolution");
  for(var j=0;j<jobs.length;j++){ var h=jobs[j][1]/spd[m]; var t=h<48?h.toFixed(1)+" h":(h/24).toFixed(1)+" days"; console.log("  "+jobs[j][0]+" ("+jobs[j][1]+" kg): "+t); }
}

